"""Recorded-date maps with failure visibility and an accessible outcome table."""
import html
import json
import math
from urllib.parse import quote
from build_loop_current_recorded_dates import ROOT, OUTPUT
from build_cartographic_current_state_join import project

def build():
    series=json.loads(OUTPUT.read_bytes());frames=[];rows=[]
    for row in series['dates']:
        noaa=json.loads((ROOT/row['noaa_diagnostic_file']).read_bytes());adt=json.loads((ROOT/row['adt_diagnostic_file']).read_bytes())
        def path(coords):return ' '.join(('M' if i==0 else 'L')+' %.5f %.5f'%project(*p) for i,p in enumerate(coords))
        query={'collection':'objects','filters':[{'field':'id','op':'eq','value':'current:loop'}],
            'geometry_time':{'from':row['date'],'to':row['date']},'limit':1}
        link='query.html?q='+quote(json.dumps(query,separators=(',',':')))+'#query-map-section'
        def display(value):return f'{int(math.floor(value/100+.5)*100):,} km' if value is not None else 'unresolved'
        frames.append({'date':row['date'],'noaa_path':path(noaa['nominal']['coordinates_lon_lat']),
            'adt_path':path(adt['selected']['coordinates_lon_lat']) if adt['selected'] else None,
            'noaa_connected':noaa['nominal']['gate_connected'],'noaa_display':display(row['noaa_connected_length_km']),
            'adt_display':display(row['adt_selected_length_km']),'noaa_stop':row['noaa_stop_reason'].replace('_',' '),
            'failed_scenarios':row['noaa_failed_scenario_count'],'difference':row['signed_difference_duacs_minus_noaa_km'],
            'query_url':link,'noaa_file':'../'+row['noaa_diagnostic_file'],'adt_file':'../'+row['adt_diagnostic_file']})
        cells=[row['date'],display(row['noaa_connected_length_km']),row['noaa_stop_reason'].replace('_',' '),
            row['noaa_failed_scenario_count'],display(row['adt_selected_length_km']),
            str(row['signed_difference_duacs_minus_noaa_km'])+' km' if row['signed_difference_duacs_minus_noaa_km'] is not None else 'unresolved']
        rows.append('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in cells)+f'<td><a href="{html.escape(link)}">Query this date</a></td></tr>')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loop Current recorded dates · OSW</title><style>\nbody{margin:0;background:#092b39;color:#e3f1f4;font:16px/1.5 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:24px}a{color:#8be9da}h1{line-height:1.15}svg{display:block;width:100%;max-height:600px;background:#092b39}.noaa{fill:none;stroke:#ffbb71;stroke-width:.5}.failed{stroke:#b4c4cf;stroke-dasharray:.7 .5}.adt{fill:none;stroke:#82e8fa;stroke-width:.35;stroke-dasharray:2 .4}.gate{fill:none;stroke:#8be9da;stroke-width:.65}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}button,select{font:inherit;padding:6px;background:#143e4c;color:inherit;border:1px solid #608793;border-radius:4px}:focus-visible{outline:3px solid #ffd36e}.table-wrap{overflow:auto}table{border-collapse:collapse;font-size:14px;width:100%}th,td{padding:9px;text-align:left;border-bottom:1px solid #37606c}.status{color:#ffd36e}p{max-width:85ch}\n</style></head><body><main><a href="query.html">Query atlas</a> · <a href="loop-current-experiment.html">September 2026 comparison</a><p class="status">RECORDED DAYS · UNRANKED DIAGNOSTICS</p><h1>Loop Current through four recorded dates</h1><p>The same two methods are applied to 15 January, April, July and October 2025. NOAA connects the gates only in April; its other selected traces stop at missing velocities. DUACS returns a connected contour on each date. Four days do not establish annual extrema, seasonal phases or a climatology.</p><div class="controls" hidden id="controls"><label for="recorded-date">Recorded day</label><select id="recorded-date"></select><button id="previous" type="button">Previous</button><button id="next" type="button">Next</button><button id="play" type="button" aria-pressed="false">Play recorded days</button></div><p id="outcome" aria-live="polite"></p><figure><svg viewBox="417.666667 332.555556 57.555556 45.222222" role="img" aria-labelledby="map-title map-desc"><title id="map-title">Recorded Loop Current methods</title><desc id="map-desc">Solid orange is a connected NOAA trace, short-dashed gray is a failed NOAA trace, long-dashed cyan is the DUACS ADT contour. Teal lines show editorial gateways. Playback steps between the four recorded dates without interpolating paths.</desc><image href="../figures/ocean-motion-closeup-ground.svg" x="60" y="90" width="1480" height="740"/><path class="gate" d="M 442.847222 370.069444 L 450.041667 370.069444"><title>Editorial Yucatan gate</title></path><path class="gate" d="M 464.944444 365.444444 L 464.944444 357.222222"><title>Editorial Florida gate</title></path><path id="noaa-line" class="noaa"><title id="noaa-title">NOAA trace</title></path><path id="adt-line" class="adt"><title id="adt-title">DUACS contour</title></path></svg><figcaption>Solid orange: connected NOAA integration. Short-dashed gray: failed NOAA integration. Long-dashed cyan: selected DUACS contour. A stopped trace is not a current length. Equirectangular projection, 93–79 W and 20–31 N; coastline is the coarse OSW display. Lengths use WGS84 geodesics.</figcaption></figure><p><a id="query-date" href="query.html">Query selected recorded day</a> · <a id="noaa-source" href="../research/loop-current-recorded-date-comparison.json">NOAA diagnostic</a> · <a id="adt-source" href="../research/loop-current-recorded-date-comparison.json">DUACS diagnostic</a></p><noscript><p>The date controls require JavaScript. All recorded outcomes and query links are available in the table below.</p></noscript><h2>All retained date outcomes</h2><p>Display lengths are rounded to 100 km. The method difference retains calculation precision; it is not an uncertainty interval. Failed scenarios include seed, integration-step and threshold checks.</p><div class="table-wrap"><table><caption>Four predeclared days; no interpolation or annual range.</caption><thead><tr><th scope="col">Date</th><th scope="col">NOAA connected</th><th scope="col">NOAA outcome</th><th scope="col">Failed scenarios</th><th scope="col">DUACS contour</th><th scope="col">DUACS − NOAA</th><th scope="col">Atlas</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><h2>Rules and limits</h2><p>NOAA RADS: 0.25-degree absolute surface geostrophic velocity. GCOOS/Copernicus DUACS: 0.125-degree absolute dynamic topography and geostrophic velocity, product P1D_202411. Grid spacing is not effective resolution. The products may share satellite observations; this comparison is not independent validation. No whole-current length, width, physical uncertainty range or named-eddy identity is admitted.</p><p>The source-use, regional gateways, effective resolution and original supplemental method reviews remain open. Missing days stay missing. Playback changes only the selected recorded snapshot; it does not show a particle trajectory or continuous physical evolution. Playback advances at equal viewing intervals, not elapsed physical time.</p><p><a href="../plans/loop-current-dated-streamline-protocol-v1.md">NOAA rules</a> · <a href="../plans/loop-current-adt-contour-protocol-v1.md">ADT rules</a> · <a href="../research/loop-current-recorded-date-comparison.json">Comparison and receipts</a></p></main><script id="recorded-frames" type="application/json">'+json.dumps(frames,separators=(',',':')).replace('<','\u003c')+'</script><script src="loop-current-recorded-dates.js?v=1"></script></body></html>'

if __name__=='__main__':
    (ROOT/'almanac/loop-current-recorded-dates.html').write_text(build(),encoding='utf-8',newline='\n')
    print('Rendered recorded-date maps')
